// 1. Fast in-memory increment
export async function recordPageView(pageId: string) {
  // Atomic in-memory increment (<1ms)
  await redis.hincrby("page_views_buffer", pageId, 1);
}

// 2. Scheduled background worker flushes batched increments every 10 seconds
export async function flushPageViewsToDatabase(db: DatabaseClient) {
  const snapshot = await redis.hgetall("page_views_buffer");
  if (!snapshot || Object.keys(snapshot).length === 0) return;

  // Atomically swap or delete flushed keys
  await redis.del("page_views_buffer");

  const entries = Object.entries(snapshot);
  // Batch UPSERT into relational database
  const sql = `
    INSERT INTO page_metrics (page_id, view_count)
    VALUES ${entries.map(([id, cnt]) => `('${id}', ${cnt})`).join(",")}
    ON CONFLICT (page_id)
    DO UPDATE SET view_count = page_metrics.view_count + EXCLUDED.view_count;
  `;
  await db.query(sql);
}
